    {
      name: 'ticket_create',
      description: 'Create a support ticket with a title, description, and optional priority.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Short summary of the issue.' },
          description: { type: 'string', description: 'Detailed description of the issue.' },
          priority: { type: 'string', enum: PRIORITIES, description: 'Ticket priority. Defaults to "normal".' },
        },
        required: ['title', 'description'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'ticket_create') {
    throw new Error('Unknown tool: ' + name);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = ['title', 'description', 'priority'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error('Unknown argument: ' + key);
    }
  }

  const { title, description } = args;

  if (typeof title !== 'string' || title.trim() === '') {
    throw new Error('title is required and must be a non-empty string');
  }
  if (typeof description !== 'string' || description.trim() === '') {
    throw new Error('description is required and must be a non-empty string');
  }

  let priority = 'normal';
  if (args.priority !== undefined) {
    if (typeof args.priority !== 'string' || !PRIORITIES.includes(args.priority)) {
      throw new Error('priority must be one of: ' + PRIORITIES.join(', '));
    }
    priority = args.priority;
  }

  const id = nextId++;
  const text = `Created ticket t${id}: "${title}" [${priority}]`;

  return {
    content: [{ type: 'text', text }],
  };
}

